using namespace std;

void solve() {
    int n;
    cin >> n;
    vector<int> a(n);
    for (int i = 0; i < n; i++) {
        cin >> a[i];
    }
    sort(a.begin(), a.end());
    a.resize(unique(a.begin(), a.end()) - a.begin());
    int pnt = 0, ans = 0;
    for (int i = 0; i < a.size(); i++) {
        while(a[i] - a[pnt] >= n) {
            pnt++;
        }
        ans = max(ans, i - pnt + 1);
    }
    cout << ans << endl;
}

signed main() {
    int t = 1;
    cin >> t;
    for (int i = 0; i < t; ++i) {
        solve();
    }
    return 0;
}

#include <iostream>
#include <unordered_set>

using namespace std;

unordered_set<int> solve(int a) {
    unordered_set<int> candidates;
    for (int i = 1; i * i <= a; i++) {
        if (a % i == 0) {
            if (i % 2 == 0) // segment len should be even
                candidates.insert(i);
            if ((a / i) % 2 == 0)
                candidates.insert(a / i);
        }
    }
    unordered_set<int> answer;
    for (int i : candidates) {
        answer.insert(1 + i / 2);
    }
    return answer;
}

int main() {
    int t;
    cin >> t;
    for (int _ = 1; _ <= t; _++) {
        int n, pos;
        cin >> n >> pos;
        unordered_set<int> candidates = solve(n - pos);  // bug2
        for (int i : solve(n + pos - 2)) { // bug1
            candidates.insert(i);
        }
        int answer = 0;
        for (int i : candidates) {
            if (i >= pos) {
                answer++;
            }
        }
        cout << answer << endl;
    }
}

#include <iostream>
#include <vector>

using namespace std;
using ll = long long;

ll pairs(ll n, ll k){
    if (n == 0 || k == 0){
        return 0;
    }
    ll x = n / k;
    ll l = n % k;
    ll r = k - l;
    ll L = (x + 1) * l, R = x * r;
    return R * L + (R - x) * R / 2 + L * (L - x - 1) / 2;
}

void solve(){
    int m;
    long long c, b;
    cin >> m >> b >> c;

    int n = 0;
    vector<int> cnt(m);
    for (int i = 0; i < m; ++i) {
        cin >> cnt[i];
        n = max(n, cnt[i]);
    }


    vector<long long> pair(n + 1);
    vector<long long> add(n + 1);
    for (int i = 0; i < m; ++i) {
        for (int j = 1; j <= cnt[i]; ++j) {
            pair[j] += pairs(cnt[i], j);
        }
        add[cnt[i]] += pairs(cnt[i], cnt[i]);
    }


    long long ans = 0;
    long long other = 0;
    for (int i = 1; i <= n; ++i) {
        ans = max(ans, b * (pair[i] + other) - c * (i - 1));
        other += add[i];
    }
    cout << ans << endl;
}

int main(){
    int t;
    cin >> t;
    while (t--){
        solve();
    }
}

